/// <summary>
/// FormDataSource Extension PCProductLookup
/// </summary>
[ExtensionOf(formDataSourceStr(PCProductLookup, All_Items))]
final public class NDXPCProductLookup_fdsrc_Extension
{
}

Method.Source:
/// <summary>
/// Init
/// </summary>
public void init()
{
    next init();

    if(MCRFullTextParameters::isProductSearchLookupSalesItemEnabled())
    {
        this.query().dataSourceTable(tablenum(InventTable)).addRange(fieldnum(InventTable, KCS_isSalesItem)).value(queryValue(NoYes::Yes));
    }
}
